        let results = db
            .get_funders_by_text_search_score(&term)
            .await
            .unwrap()
            .matches;

        assert_eq!(results.len(), 1);
        assert_eq!(results.first().unwrap().0.funder().name(), "Aaron Banks");

        Ok(())
    }
